  4→import jlsm.core.compaction.CompactionTask;
  5→import jlsm.core.compaction.Compactor;
  6→import jlsm.core.memtable.MemTable;
  7→import jlsm.core.model.Entry;
  8→import jlsm.core.model.Level;
  9→import jlsm.core.model.SequenceNumber;
 10→import jlsm.core.sstable.SSTableMetadata;
 11→import jlsm.core.sstable.SSTableReader;
 12→import jlsm.core.tree.LsmTree;
 13→import jlsm.core.wal.WriteAheadLog;
 14→import jlsm.tree.internal.MergeIterator;
 15→
 16→import java.io.IOException;
 17→import java.lang.foreign.MemorySegment;
 18→import java.nio.file.Path;
 19→import java.util.ArrayList;
 20→import java.util.HashSet;
 21→import java.util.Iterator;
 22→import java.util.List;
 23→import java.util.Objects;
 24→import java.util.Optional;
 25→import java.util.Set;
 26→import java.util.concurrent.CopyOnWriteArrayList;
 27→import java.util.concurrent.locks.ReentrantLock;
 28→import java.util.function.BiFunction;
 29→import java.util.function.LongSupplier;
 30→import java.util.function.Supplier;
 31→
 32→/**
 33→ * Standard LSM-Tree implementation that composes a WAL, MemTable, SSTableWriter, and SSTableReader.
 34→ *
 35→ * <p>
 36→ * <b>Write path</b>: every mutation is first appended to the WAL (assigned a sequence number), then
 37→ * applied to the active MemTable. When {@code approximateSizeBytes() >= flushThresholdBytes}, the
 38→ * MemTable is rotated and flushed to an L0 SSTable.
 39→ *
 40→ * <p>
 41→ * <b>Read path</b>: the active MemTable is checked first, then each SSTable reader in newest-first
 42→ * order (index 0 = most recently flushed).
 43→ *
 44→ * <p>
 45→ * <b>Threading</b>: writes and flushes are serialised by a single {@link ReentrantLock}; reads
 46→ * ({@link #get}, {@link #scan}) are lock-free because {@link CopyOnWriteArrayList} provides a
 47→ * consistent snapshot of the SSTable reader list.
 48→ */
 49→public final class StandardLsmTree implements LsmTree {
 50→
 51→    private static final long DEFAULT_FLUSH_THRESHOLD = 64L * 1024 * 1024; // 64 MiB
 52→
 53→    private final WriteAheadLog wal;
 54→    private final Supplier<MemTable> memTableFactory;
 55→    private final SSTableWriterFactory writerFactory;
 56→    private final SSTableReaderFactory readerFactory;
 57→    private final LongSupplier idSupplier;
 58→    private final BiFunction<Long, Level, Path> pathFn;
 59→    private final long flushThresholdBytes;
 60→    private final Compactor compactor;
 61→
 62→    /** The MemTable currently accepting writes. Rotated under {@link #writeLock}. */
 63→    private volatile MemTable activeMemTable;
 64→
 65→    /**
 66→     * SSTable readers in newest-first order (index 0 = most recently flushed L0 file). Reads are
 67→     * lock-free; flushes prepend under {@link #writeLock}.
 68→     */
 69→    private final CopyOnWriteArrayList<SSTableReader> sstableReaders;
 70→
 71→    private final ReentrantLock writeLock = new ReentrantLock();
 72→    private volatile boolean closed = false;
 73→
 74→    private StandardLsmTree(Builder builder, MemTable initialMemTable,
 75→            CopyOnWriteArrayList<SSTableReader> existingReaders) {
 76→        this.wal = builder.wal;
 77→        this.memTableFactory = builder.memTableFactory;
 78→        this.writerFactory = builder.writerFactory;
 79→        this.readerFactory = builder.readerFactory;
 80→        this.idSupplier = builder.idSupplier;
 81→        this.pathFn = builder.pathFn;
 82→        this.flushThresholdBytes = builder.flushThresholdBytes;
 83→        this.compactor = builder.compactor;
 84→        this.activeMemTable = initialMemTable;
 85→        this.sstableReaders = existingReaders;
 86→    }
 87→
 88→    // -----------------------------------------------------------------------
 89→    // Write path
 90→    // -----------------------------------------------------------------------
 91→
 92→    @Override
 93→    public void put(MemorySegment key, MemorySegment value) throws IOException {
 94→        Objects.requireNonNull(key, "key must not be null");
 95→        Objects.requireNonNull(value, "value must not be null");
 96→        checkNotClosed();
 97→
 98→        writeLock.lock();
 99→        try {
100→            // WAL assigns the sequence number; pass ZERO as sentinel for the initial entry
101→            SequenceNumber seq = wal.append(new Entry.Put(key, value, SequenceNumber.ZERO));
102→            activeMemTable.apply(new Entry.Put(key, value, seq));
103→            maybeFlush();
104→        } finally {
105→            writeLock.unlock();
106→        }
107→    }
108→
109→    @Override
110→    public void delete(MemorySegment key) throws IOException {
111→        Objects.requireNonNull(key, "key must not be null");
112→        checkNotClosed();
113→
114→        writeLock.lock();
115→        try {
116→            SequenceNumber seq = wal.append(new Entry.Delete(key, SequenceNumber.ZERO));
117→            activeMemTable.apply(new Entry.Delete(key, seq));
118→            maybeFlush();
119→        } finally {
120→            writeLock.unlock();
121→        }
122→    }
123→
124→    /**
125→     * Flushes if the active MemTable has grown past the threshold. Must hold {@link #writeLock}.
126→     */
127→    private void maybeFlush() throws IOException {
128→        if (activeMemTable.approximateSizeBytes() >= flushThresholdBytes) {
129→            flush();
130→            maybeCompact();
131→        }
132→    }
133→
134→    /**
135→     * Runs one round of compaction if the compactor selects a task. Must hold {@link #writeLock}.
136→     */
137→    private void maybeCompact() throws IOException {
138→        List<List<SSTableMetadata>> levelMetadata = buildLevelMetadata();
139→        Optional<CompactionTask> task = compactor.selectCompaction(levelMetadata);
140→        if (task.isPresent()) {
141→            List<SSTableMetadata> outputs = compactor.compact(task.get());
142→            applyCompactionResult(task.get(), outputs);
143→        }
144→    }
145→
146→    private List<List<SSTableMetadata>> buildLevelMetadata() {
147→        int maxLevel = 0;
148→        for (SSTableReader reader : sstableReaders) {
149→            maxLevel = Math.max(maxLevel, reader.metadata().level().index());
150→        }
151→        List<List<SSTableMetadata>> result = new ArrayList<>();
152→        for (int i = 0; i <= maxLevel; i++) {
153→            result.add(new ArrayList<>());
154→        }
155→        for (SSTableReader reader : sstableReaders) {
156→            result.get(reader.metadata().level().index()).add(reader.metadata());
157→        }
158→        return result;
159→    }
160→
161→    private void applyCompactionResult(CompactionTask task, List<SSTableMetadata> outputs)
162→            throws IOException {
163→        Set<Long> sourceIds = new HashSet<>();
164→        for (SSTableMetadata m : task.sourceSSTables()) {
165→            sourceIds.add(m.id());
166→        }
167→        List<SSTableReader> toClose = new ArrayList<>();
168→        sstableReaders.removeIf(r -> {
169→            if (sourceIds.contains(r.metadata().id())) {
170→                toClose.add(r);
171→                return true;
172→            }
173→            return false;
174→        });
175→        for (SSTableMetadata out : outputs) {
176→            sstableReaders.add(readerFactory.open(out.path()));
177→        }
178→        for (SSTableReader r : toClose) {
179→            try {
180→                r.close();
181→            } catch (IOException ignored) {
182→            }
183→        }
184→    }
185→
186→    /**
187→     * Rotates the active MemTable and writes its contents to a new L0 SSTable. Must hold
188→     * {@link #writeLock}.
189→     */
190→    private void flush() throws IOException {
191→        if (activeMemTable.isEmpty())
192→            return;
193→
194→        MemTable immutable = activeMemTable;
195→        activeMemTable = memTableFactory.get();
196→
197→        long id = idSupplier.getAsLong();
198→        Path path = pathFn.apply(id, Level.L0);
199→
200→        SequenceNumber maxSeq = SequenceNumber.ZERO;
201→
202→        try (var writer = writerFactory.create(id, Level.L0, path)) {
203→            MemorySegment lastKey = null;
204→            Iterator<Entry> it = immutable.scan();
205→            while (it.hasNext()) {
206→                Entry entry = it.next();
207→                // MemTable.scan() yields multiple seqNums per key (DESC); skip older versions
208→                if (lastKey != null && MergeIterator.keysEqual(lastKey, entry.key())) {
209→                    continue;
210→                }
211→                lastKey = entry.key();
212→                writer.append(entry);
213→                if (entry.sequenceNumber().compareTo(maxSeq) > 0) {
214→                    maxSeq = entry.sequenceNumber();
215→                }
216→            }
217→            writer.finish();
218→        }
219→
220→        SSTableReader reader = readerFactory.open(path);
221→        sstableReaders.add(0, reader); // prepend: newest at index 0
222→
223→        // Truncate WAL entries that are now safely persisted in the SSTable
224→        wal.truncateBefore(maxSeq.next());
225→    }
226→
227→    // -----------------------------------------------------------------------
228→    // Read path
229→    // -----------------------------------------------------------------------
230→
231→    @Override
232→    public Optional<MemorySegment> get(MemorySegment key) throws IOException {
233→        Objects.requireNonNull(key, "key must not be null");
234→        checkNotClosed();
235→
236→        // Check active MemTable first (lock-free: ConcurrentSkipListMemTable is thread-safe)
237→        Optional<Entry> memResult = activeMemTable.get(key);
238→        if (memResult.isPresent()) {
239→            return mapEntry(memResult.get());
240→        }
241→
242→        // Fall through to SSTables, newest first
243→        for (SSTableReader reader : sstableReaders) {
244→            Optional<Entry> sstResult = reader.get(key);
245→            if (sstResult.isPresent()) {
246→                return mapEntry(sstResult.get());
247→            }
248→        }
249→
250→        return Optional.empty();
251→    }
252→
253→    @Override
254→    public Iterator<Entry> scan() throws IOException {
255→        checkNotClosed();
256→
257→        List<Iterator<Entry>> sources = new ArrayList<>();
258→        sources.add(activeMemTable.scan());
259→        for (SSTableReader reader : sstableReaders) {
260→            sources.add(reader.scan());
261→        }
262→        return new MergeIterator(sources);
263→    }
264→
265→    @Override
266→    public Iterator<Entry> scan(MemorySegment from, MemorySegment to) throws IOException {
267→        Objects.requireNonNull(from, "from must not be null");
268→        Objects.requireNonNull(to, "to must not be null");
269→        checkNotClosed();
270→
271→        List<Iterator<Entry>> sources = new ArrayList<>();
272→        sources.add(activeMemTable.scan(from, to));
273→        for (SSTableReader reader : sstableReaders) {
274→            sources.add(reader.scan(from, to));
275→        }
276→        return new MergeIterator(sources, from, to);
277→    }
278→
279→    /** Maps an Entry to an Optional value: Put → value present, Delete → empty. */
280→    private static Optional<MemorySegment> mapEntry(Entry entry) {
281→        return switch (entry) {
282→            case Entry.Put put -> Optional.of(put.value());
283→            case Entry.Delete _ -> Optional.empty();
284→        };
285→    }
286→
287→    // -----------------------------------------------------------------------
288→    // Lifecycle
289→    // -----------------------------------------------------------------------
290→
291→    @Override
292→    public void close() throws IOException {
293→        closed = true;
294→        IOException deferred = null;
295→
296→        try {
297→            wal.close();
298→        } catch (IOException e) {
299→            deferred = e;
300→        }
301→
302→        for (SSTableReader reader : sstableReaders) {
303→            try {
304→                reader.close();
305→            } catch (IOException e) {
306→                if (deferred == null)
307→                    deferred = e;
308→                else
309→                    deferred.addSuppressed(e);
310→            }
311→        }
312→
313→        if (compactor instanceof AutoCloseable ac) {
314→            try {
315→                ac.close();
316→            } catch (Exception e) {
317→                if (deferred == null && e instanceof IOException io)
318→                    deferred = io;
319→                else if (deferred != null)
320→                    deferred.addSuppressed(e);
321→            }
322→        }
323→
324→        if (deferred != null)
325→            throw deferred;
326→    }
327→
328→    private void checkNotClosed() {
329→        if (closed)
330→            throw new IllegalStateException("LsmTree is closed");
331→    }
332→
333→    // -----------------------------------------------------------------------
334→    // Builder
335→    // -----------------------------------------------------------------------
336→
337→    public static Builder builder() {
338→        return new Builder();
339→    }
340→
341→    public static final class Builder {
342→        private WriteAheadLog wal;
343→        private Supplier<MemTable> memTableFactory;
344→        private SSTableWriterFactory writerFactory;
345→        private SSTableReaderFactory readerFactory;
346→        private LongSupplier idSupplier;
347→        private BiFunction<Long, Level, Path> pathFn;
348→        private long flushThresholdBytes = DEFAULT_FLUSH_THRESHOLD;
349→        private boolean recoverFromWal = true;
350→        private List<SSTableReader> existingSSTables = List.of();
351→        private Compactor compactor;
352→        private jlsm.core.bloom.BloomFilter.Deserializer bloomDeserializer;
353→
354→        public Builder wal(WriteAheadLog wal) {
355→            this.wal = Objects.requireNonNull(wal, "wal must not be null");
356→            return this;
357→        }
358→
359→        public Builder memTableFactory(Supplier<MemTable> memTableFactory) {
360→            this.memTableFactory = Objects.requireNonNull(memTableFactory,
361→                    "memTableFactory must not be null");
362→            return this;
363→        }
364→
365→        public Builder sstableWriterFactory(SSTableWriterFactory writerFactory) {
366→            this.writerFactory = Objects.requireNonNull(writerFactory,
367→                    "writerFactory must not be null");
368→            return this;
369→        }
370→
371→        public Builder sstableReaderFactory(SSTableReaderFactory readerFactory) {
372→            this.readerFactory = Objects.requireNonNull(readerFactory,
373→                    "readerFactory must not be null");
374→            return this;
375→        }
376→
377→        public Builder idSupplier(LongSupplier idSupplier) {
378→            this.idSupplier = Objects.requireNonNull(idSupplier, "idSupplier must not be null");
379→            return this;
380→        }
381→
382→        public Builder pathFn(BiFunction<Long, Level, Path> pathFn) {
383→            this.pathFn = Objects.requireNonNull(pathFn, "pathFn must not be null");
384→            return this;
385→        }
386→
387→        public Builder memTableFlushThresholdBytes(long bytes) {
388→            if (bytes <= 0) {
389→                throw new IllegalArgumentException(
390→                        "flushThresholdBytes must be positive, got: " + bytes);
391→            }
392→            this.flushThresholdBytes = bytes;
393→            return this;
394→        }
395→
396→        public Builder recoverFromWal(boolean recover) {
397→            this.recoverFromWal = recover;
398→            return this;
399→        }
400→
401→        public Builder existingSSTables(List<SSTableReader> readers) {
402→            this.existingSSTables = Objects.requireNonNull(readers,
403→                    "existingSSTables must not be null");
404→            return this;
405→        }
406→
407→        public Builder compactor(Compactor compactor) {
408→            this.compactor = Objects.requireNonNull(compactor, "compactor must not be null");
409→            return this;
410→        }
411→
412→        /**
413→         * Overrides the bloom-filter deserializer passed to the default {@link SpookyCompactor}
414→         * when no explicit {@link #compactor} is set. Must match the filter used when writing the
415→         * SSTables this tree will compact. If not set, defaults to
416→         * {@code BlockedBloomFilter.deserializer()}.
417→         */
418→        public Builder bloomDeserializer(jlsm.core.bloom.BloomFilter.Deserializer deserializer) {
419→            this.bloomDeserializer = Objects.requireNonNull(deserializer,
420→                    "bloomDeserializer must not be null");
421→            return this;
422→        }
423→
424→        public StandardLsmTree build() throws IOException {
425→            Objects.requireNonNull(wal, "wal must not be null");
426→            Objects.requireNonNull(memTableFactory, "memTableFactory must not be null");
427→            Objects.requireNonNull(writerFactory, "writerFactory must not be null");
428→            Objects.requireNonNull(readerFactory, "readerFactory must not be null");
429→            Objects.requireNonNull(idSupplier, "idSupplier must not be null");
430→            Objects.requireNonNull(pathFn, "pathFn must not be null");
431→
432→            if (compactor == null) {
433→                SpookyCompactor.Builder compactorBuilder = SpookyCompactor.builder()
434→                        .idSupplier(idSupplier).pathFn(pathFn);
435→                if (bloomDeserializer != null) {
436→                    compactorBuilder.bloomDeserializer(bloomDeserializer);
437→                }
438→                compactor = compactorBuilder.build();
439→            }
440→
441→            MemTable initialMemTable = memTableFactory.get();
442→
443→            if (recoverFromWal) {
444→                Iterator<Entry> replayed = wal.replay(SequenceNumber.ZERO);
445→                replayed.forEachRemaining(initialMemTable::apply);
446→            }
447→
448→            return new StandardLsmTree(this, initialMemTable,
449→                    new CopyOnWriteArrayList<>(existingSSTables));
450→        }
451→    }
452→}
