170→    // -----------------------------------------------------------------------
171→    // StringKeyed
172→    // -----------------------------------------------------------------------
173→
174→    /**
175→     * A {@link TypedLsmTree.StringKeyed} that delegates to a {@link StandardLsmTree} and encodes
176→     * keys as UTF-8 bytes.
177→     *
178→     * @param <V> the value type
179→     */
180→    public static final class StringKeyed<V> implements TypedLsmTree.StringKeyed<V> {
181→
182→        private final StandardLsmTree delegate;
183→        private final MemorySerializer<V> valueSerializer;
184→
185→        private StringKeyed(StandardLsmTree delegate, MemorySerializer<V> valueSerializer) {
186→            assert delegate != null : "delegate must not be null";
187→            assert valueSerializer != null : "valueSerializer must not be null";
188→            this.delegate = delegate;
189→            this.valueSerializer = valueSerializer;
190→        }
191→
192→        @Override
193→        public void put(String key, V value) throws IOException {
194→            Objects.requireNonNull(key, "key must not be null");
195→            Objects.requireNonNull(value, "value must not be null");
196→            delegate.put(encodeString(key), valueSerializer.serialize(value));
197→        }
198→
199→        @Override
200→        public void delete(String key) throws IOException {
201→            Objects.requireNonNull(key, "key must not be null");
202→            delegate.delete(encodeString(key));
203→        }
204→
205→        @Override
