 1→package jlsm.core.sstable;
 2→
 3→import jlsm.core.model.Level;
 4→import jlsm.core.model.SequenceNumber;
 5→
 6→import java.lang.foreign.MemorySegment;
 7→import java.nio.file.Path;
 8→import java.util.Objects;
 9→
10→/**
11→ * Immutable descriptor for an SSTable file, capturing its identity, location, key range, sequence
12→ * number range, and size statistics.
13→ *
14→ * <p>
15→ * <b>Pipeline position</b>: Produced by {@link SSTableWriter#finish} and consumed by
16→ * {@link SSTableReader}, the Compactor (for compaction selection), and the block cache (for
17→ * eviction). Does not hold open file handles.
18→ *
19→ * <p>
20→ * <b>Key contracts</b>:
21→ * <ul>
22→ * <li>{@code id} is unique within a store instance; typically a monotonically increasing counter
23→ * assigned at flush time.</li>
24→ * <li>{@code smallestKey} and {@code largestKey} define the inclusive key range of this SSTable;
25→ * used by compaction selection to find overlapping files.</li>
26→ * <li>{@code minSequence} and {@code maxSequence} bound the sequence numbers of all entries in this
27→ * file; used for snapshot isolation and WAL truncation.</li>
28→ * </ul>
29→ *
30→ * @param id unique identifier for this SSTable within the store
31→ * @param path absolute path to the SSTable file on disk
32→ * @param level the LSM level at which this SSTable resides
33→ * @param smallestKey the inclusive smallest key in this SSTable; must not be null
34→ * @param largestKey the inclusive largest key in this SSTable; must not be null
35→ * @param minSequence the smallest sequence number among all entries; must not be null
36→ * @param maxSequence the largest sequence number among all entries; must not be null
37→ * @param sizeBytes the file size in bytes; must be non-negative
38→ * @param entryCount the total number of entries (including tombstones); must be non-negative
39→ */
40→public record SSTableMetadata(long id, Path path, Level level, MemorySegment smallestKey,
41→        MemorySegment largestKey, SequenceNumber minSequence, SequenceNumber maxSequence,
42→        long sizeBytes, long entryCount) {
43→    public SSTableMetadata {
44→        Objects.requireNonNull(path, "path must not be null");
45→        Objects.requireNonNull(level, "level must not be null");
46→        Objects.requireNonNull(smallestKey, "smallestKey must not be null");
47→        Objects.requireNonNull(largestKey, "largestKey must not be null");
48→        Objects.requireNonNull(minSequence, "minSequence must not be null");
49→        Objects.requireNonNull(maxSequence, "maxSequence must not be null");
50→        if (sizeBytes < 0) {
51→            throw new IllegalArgumentException("sizeBytes must be non-negative, got: " + sizeBytes);
52→        }
53→        if (entryCount < 0) {
54→            throw new IllegalArgumentException(
55→                    "entryCount must be non-negative, got: " + entryCount);
56→        }
57→    }
58→}
